contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient, address a1, address a2, uint amount) public {
        c.init(address(this), address(this), address(this));
        c.newGrantProposal(recipient, amount);            // pid1, type GRANT
        c.newGrantProposal(recipient, amount);            // pid2, type GRANT
        c.newAddressProposal(a1, "GRANTX");               // pid3
        c.newAddressProposal(a2, "DIFF");                 // pid4
        uint pid1 = c.proposalCount() - 3;
        uint pid2 = c.proposalCount() - 2;
        uint pid3 = c.proposalCount() - 1;
        uint pid4 = c.proposalCount();
        c.voteProposal(pid1);
        c.voteProposal(pid2);
        c.voteProposal(pid3);
        c.voteProposal(pid4);
        require(c.mapPID_finalising(pid1));
        require(c.mapPID_finalising(pid3));
        require(c.hasMinority(pid2));
        require(c.hasMinority(pid4));
        uint votesOld1 = c.mapPID_votes(pid1);
        bool ok1;
        bool ok2;
        try c.cancelProposal(pid1, pid2) { ok1 = true; } catch { ok1 = false; }
        try c.cancelProposal(pid3, pid4) { ok2 = true; } catch { ok2 = false; }
        assert(ok1 && !ok2 && votesOld1 > 0 && c.mapPID_votes(pid1) == 0 && c.mapPID_votes(pid3) > 0);
    }
    fallback(bytes calldata input) external payable returns (bytes memory) {
        bytes4 sel = bytes4(input[:4]);
        if (sel == iVAULT.getMemberWeight.selector) {
            return abi.encode(300);
        }
        if (sel == iVAULT.totalWeight.selector) {
            return abi.encode(600);
        }
        return "";
    }
    receive() external payable {}
}

